    def setUpClass(cls):
        path=Path(__file__).resolve().parent.parent/'flower_author_template_audit_20261019_v1/results_v2/event_inputs.jsonl.gz'
        ids={f'gt:textbook-tool-sft:flower_mech_proof_test_37:{i}' for i in (5,6)}
